/** Stands in for mariadb-admin: `shutdown` over TCP. Refuses without a password in MYSQL_PWD. */
import net from 'node:net'

const port = Number(process.argv.find((a) => a.startsWith('--port='))?.slice(7))
if (!process.env.MYSQL_PWD) {
  process.stderr.write('fake admin: Access denied (no password)\n')
  process.exit(1)
}
if (process.argv.at(-1) !== 'shutdown') process.exit(2)
const s = net.createConnection(port, '127.0.0.1', () => s.write('shutdown\n'))
s.on('data', () => { s.end(); process.exit(0) })
s.on('error', (e) => { process.stderr.write(`fake admin: ${e.message}\n`); process.exit(1) })

/** Stands in for mariadb-dump --databases <db>: asks the fake server for a dump and prints it. */
import net from 'node:net'

const argv = process.argv
const port = Number(argv.find((a) => a.startsWith('--port='))?.slice(7))
const db = argv[argv.indexOf('--databases') + 1]
if (!process.env.MYSQL_PWD) {
  process.stderr.write("fake dump: Access denied for user 'root'@'localhost'\n")
  process.exit(1)
}
if (!db) process.exit(2)
const s = net.createConnection(port, '127.0.0.1', () => s.write(`dump ${Buffer.from(db).toString('base64')}\n`))
let buf = ''
s.on('data', (d) => { buf += d })
s.on('end', () => {
  const line = buf.trim()
  if (!line.startsWith('ok ')) { process.stderr.write('fake dump: server refused\n'); process.exit(1) }
  process.stdout.write(Buffer.from(line.slice(3), 'base64').toString('utf8'))
  process.exit(0)
})
s.on('error', (e) => { process.stderr.write(`fake dump: ${e.message}\n`); process.exit(1) })

/**
 * Stands in for mariadb-install-db: makes the data folder and records the root password in it,
 * which is where the other fakes look to check what the real tools check over the wire.
 */
import fs from 'node:fs'
import path from 'node:path'

const arg = (k) => process.argv.find((a) => a.startsWith(`--${k}=`))?.slice(k.length + 3)
const datadir = arg('datadir')
if (!datadir) {
  process.stderr.write('fake install-db: --datadir is required\n')
  process.exit(2)
}
fs.mkdirSync(path.join(datadir, 'mysql'), { recursive: true })
fs.writeFileSync(path.join(datadir, 'root.txt'), arg('password') ?? '')
fs.writeFileSync(path.join(datadir, 'port.txt'), arg('port') ?? '')
process.stdout.write('fake install-db: done\n')

/** Stands in for the mariadb client with --execute: ships the statements to the fake server. */
import net from 'node:net'

const argv = process.argv
const port = Number(argv.find((a) => a.startsWith('--port='))?.slice(7))
const at = argv.indexOf('--execute')
if (!process.env.MYSQL_PWD) {
  process.stderr.write("fake client: ERROR 1045 (28000): Access denied for user 'root'@'localhost'\n")
  process.exit(1)
}
// --execute carries the statements; without it they arrive on stdin, the way an import does.
const text = at === -1 ? await new Promise((resolve) => { let b = ''; process.stdin.on('data', (c) => { b += c }); process.stdin.on('end', () => resolve(b)) }) : argv[at + 1]
const s = net.createConnection(port, '127.0.0.1', () => s.write(`sql ${Buffer.from(text).toString('base64')}\n`))
s.on('data', (d) => { s.end(); process.exit(String(d).startsWith('ok') ? 0 : 1) })
s.on('error', (e) => { process.stderr.write(`fake client: ERROR 2002: Can't connect (${e.message})\n`); process.exit(1) })

/**
 * Stands in for mariadbd --console: reads the port and data folder from the ini, listens on
 * loopback, says "ready for connections" on stderr the way the real one does, takes no stdin,
 * and speaks a one-line protocol the fake admin and client use:
 *
 *   shutdown          exit 0 after saying so (and a line in <datadir>/fake-shutdowns.log, which
 *                     outlives the console log a restart starts again)
 *   sql <base64>      append the statements to <datadir>/sql.log, answer "ok"
 *   dump <base64 db>  answer "ok <base64 dump text>" and close, the way a dump streams
 *
 * FAKE_MARIADB_FAIL=start makes it die during startup the way a taken port does.
 * FAKE_MARIADB_STABLE_DUMP=1 leaves the time out of a dump, so two runs dump the same bytes.
 */
import fs from 'node:fs'
import net from 'node:net'
import path from 'node:path'

const ini = process.argv.find((a) => a.startsWith('--defaults-file='))?.slice('--defaults-file='.length)
const text = ini ? fs.readFileSync(ini, 'utf8') : ''
const port = Number(/^port=(\d+)/m.exec(text)?.[1])
const datadir = /^datadir=(.+)$/m.exec(text)?.[1]?.trim()
const note = (line) => process.stderr.write(`<time> 0 [Note] mariadbd: ${line}\n`)

note(`Starting fake MariaDB ${process.argv.slice(2).join(' ')}`)
if (process.env.FAKE_MARIADB_FAIL === 'start') {
  process.stderr.write("<time> 0 [ERROR] Can't start server: Bind on TCP/IP port. Got error: 10048\n")
  process.stderr.write('<time> 0 [ERROR] Aborting\n')
  process.exit(1)
}

const server = net.createServer((socket) => {
  let buf = ''
  socket.on('data', (c) => {
    buf += c.toString()
    let nl
    while ((nl = buf.indexOf('\n')) !== -1) {
      const line = buf.slice(0, nl).trim()
      buf = buf.slice(nl + 1)
      if (line === 'shutdown') {
        note('Normal shutdown')
        try {
          fs.appendFileSync(path.join(datadir, 'fake-shutdowns.log'), JSON.stringify({ pid: process.pid, at: Date.now() }) + '\n')
        } catch {
          /* the console line is the evidence then */
        }
        socket.end('ok\n')
        setTimeout(() => process.exit(0), 50)
      } else if (line.startsWith('sql ')) {
        const sql = Buffer.from(line.slice(4), 'base64').toString('utf8')
        fs.appendFileSync(path.join(datadir, 'sql.log'), sql + '\n')
        socket.write('ok\n')
      } else if (line.startsWith('dump ')) {
        const db = Buffer.from(line.slice(5), 'base64').toString('utf8')
        const text = `-- MariaDB dump (fake) of ${db}\nCREATE DATABASE IF NOT EXISTS \`${db}\`;\nUSE \`${db}\`;\n${process.env.FAKE_MARIADB_STABLE_DUMP === '1' ? '' : `-- dumped at ${Date.now()}\n`}`
        socket.end(`ok ${Buffer.from(text).toString('base64')}\n`)
      } else {
        socket.write('error unknown\n')
      }
    }
  })
  socket.on('error', () => {})
})
server.listen(port, '127.0.0.1', () => setTimeout(() => note('ready for connections.'), 150))
server.on('error', (err) => {
  process.stderr.write(`<time> 0 [ERROR] Can't start server: ${err.message}\n`)
  process.exit(1)
})
setInterval(() => {}, 1 << 30)

